"""The gate a JSON-authored node must pass before anything renders it.

Workpeg's node contract is ``{type, props, children}``, and every SINK in the
runtime is already hardened — ``textContent`` rather than ``innerHTML``, URL
allowlists, a CSS value deny-list, icon-name scrubbing. That is what makes
"authored in the SDK" safe.

It is not what makes *JSON* safe, and the difference is the reason this module
exists. ``renderNode`` never checks that ``type`` is a type it knows (an
unknown one becomes a bare ``div``), and it concatenates ``type``, ``variant``,
``tone`` and ``weight`` straight into a className without scrubbing them. Per
-sink hardening cannot catch either, because neither is a sink.

So four checks, and they are the whole of it:

1. ``type`` must be one this module knows.
2. each prop must be one that type takes.
3. the class-forming props are scrubbed to a strict shape.
4. depth and node count are capped.

**The allowlist is small on purpose.** It is display vocabulary — things that
show a person something — plus one navigational link. It is not the widget
set: a JSON document that could build a form could build a convincing fake of
one, and this is rendered inside Workpeg's own chrome where a person has every
reason to trust what they see.

**JSON cannot express the unsafe parts anyway**, which is worth stating so
nobody reads this as a subset of the SDK with parity intended. A ``component``
node is a live JS class; a ``__bound`` node stands for a live owner; a
lambda handler is a compiled function. None survive a round trip through JSON,
so a JSON renderer is restricted to plain nodes with STRING handlers — and a
string handler resolves against the host object the renderer is given, never
against the Peg's page class.
"""
import re

#: How deep a document may nest. Deep enough for a card with a list in it,
#: shallow enough that a recursive walk cannot be turned into a stack
#: overflow by somebody who noticed there was no limit.
MAX_DEPTH = 12

#: How many nodes one document may contain, counting every level.
MAX_NODES = 300

#: The longest string that may reach a text sink. Bounds one node; the node
#: count bounds the document. Applies to a bare-string child, which is how
#: text content travels.
MAX_TEXT = 2000

#: Props that end up concatenated into a className. These are the ones per
#: -sink hardening does not see, so they are held to a strict shape rather
#: than merely escaped.
CLASS_PROPS = ("variant", "tone", "weight", "size", "align")

#: A class-forming value: one lowercase word. Not a general escape — a value
#: that is not one of these is refused, because there is no legitimate reason
#: for a variant to contain punctuation and every illegitimate one ends in a
#: class nobody meant to write.
_CLASS_VALUE_RE = re.compile(r"[a-z][a-z0-9_-]{0,31}\Z")

#: An icon name. The runtime scrubs these too; this refuses earlier and more
#: plainly.
_ICON_RE = re.compile(r"[a-z0-9][a-z0-9-]{0,63}\Z")

#: A string handler resolves as ``owner[name]()`` on the renderer's host
#: object — never on the Peg's page class. The shape is held here so a name
#: cannot be ``constructor`` or reach through a prototype.
_HANDLER_RE = re.compile(r"[a-z][a-zA-Z0-9_]{0,63}\Z")
_HANDLER_DENY = frozenset({
    "constructor", "prototype", "__proto__", "toString", "valueOf",
})

#: What may be rendered, and what each one takes.
#:
#: Display vocabulary plus one link. Deliberately no input, no form, no
#: upload: a document that could build a form could build a convincing fake
#: of one, inside chrome a person has every reason to trust.
ALLOWED = {
    # VERIFIED against the runtime's own dispatch — every name here is one
    # renderNode actually branches on. Three earlier guesses (heading, card,
    # row_cell) were not, and would have validated cleanly and then rendered
    # as a bare div: exactly the failure this module exists to stop, arriving
    # through the module itself.
    #
    # Text content is CHILDREN, not a prop: `text` reads
    # `el.textContent = String(children)`, and a value prop would have
    # validated and rendered an empty span.
    "text": ("variant", "tone", "weight", "align"),
    "column": ("gap", "align"),
    "row": ("gap", "align"),
    "container": ("gap", "variant", "align"),
    "divider": (),
    "badge": ("label", "tone", "variant"),
    "icon": ("name", "size", "weight"),
    "image": ("src", "alt"),
    # A link is the one thing here that goes anywhere. Its href goes through
    # the runtime's own _safeUrl at the sink — this only bounds the shape.
    "link": ("href",),
    # A button with a STRING handler, resolved against the host object. No
    # lambda survives JSON, so this is the whole of what a JSON document can
    # make interactive.
    "button": ("label", "handler", "variant", "tone"),
    "chip": ("label", "tone", "variant"),
    "code": ("variant",),
    "table": ("gap",),
}

#: Props whose value is free text and so must be length-capped.
_TEXT_PROPS = ("value", "label", "alt")


class NodeValidationError(ValueError):
    """A node document the platform will not render."""


def _check_text(value, prop, where):
    if not isinstance(value, (str, int, float, bool)):
        raise NodeValidationError(
            f"{where}: {prop} must be text or a number")
    text = str(value)
    if len(text) > MAX_TEXT:
        raise NodeValidationError(
            f"{where}: {prop} is {len(text)} characters; the limit is "
            f"{MAX_TEXT}")
    return text


def _check_class_prop(value, prop, where):
    if not isinstance(value, str) or not _CLASS_VALUE_RE.match(value):
        raise NodeValidationError(
            f"{where}: {prop} must be one lowercase word — it is concatenated "
            f"into a class name, and nothing else belongs in one")
    return value


def _check_props(node_type, props, where):
    allowed = ALLOWED[node_type]
    out = {}
    for prop, value in (props or {}).items():
        if prop not in allowed:
            raise NodeValidationError(
                f"{where}: {node_type!r} does not take {prop!r}. It takes "
                f"{', '.join(allowed) or 'no props'}.")
        if prop in CLASS_PROPS:
            out[prop] = _check_class_prop(value, prop, where)
        elif prop in _TEXT_PROPS:
            out[prop] = _check_text(value, prop, where)
        elif prop == "name":
            if not isinstance(value, str) or not _ICON_RE.match(value):
                raise NodeValidationError(
                    f"{where}: icon name {value!r} is not a lowercase icon "
                    f"name")
            out[prop] = value
        elif prop == "handler":
            if not isinstance(value, str) or not _HANDLER_RE.match(value) \
                    or value in _HANDLER_DENY:
                raise NodeValidationError(
                    f"{where}: handler {value!r} is not a plain method name. "
                    f"It is resolved on the renderer's host object, so it may "
                    f"not reach through a prototype.")
            out[prop] = value
        elif prop in ("href", "src"):
            if not isinstance(value, str) or not value.strip():
                raise NodeValidationError(
                    f"{where}: {prop} must be a non-empty string")
            out[prop] = value.strip()
        elif prop == "gap":
            if not isinstance(value, (int, float)) or isinstance(value, bool) \
                    or not 0 <= value <= 128:
                raise NodeValidationError(
                    f"{where}: gap must be a number between 0 and 128")
            out[prop] = value
        else:
            raise NodeValidationError(
                f"{where}: {prop!r} has no validator, so it is refused. A "
                f"prop nobody checked is a prop nobody hardened.")
    return out


def validate(node, *, _depth=0, _counter=None, _where="node"):
    """Validate one node document, returning the parts that may render.

    Returns a new structure rather than the input, so nothing unchecked can
    travel by riding along on a key nobody looked at.
    """
    counter = _counter if _counter is not None else [0]

    if _depth > MAX_DEPTH:
        raise NodeValidationError(
            f"{_where}: nested deeper than {MAX_DEPTH}")
    counter[0] += 1
    if counter[0] > MAX_NODES:
        raise NodeValidationError(
            f"a node document may hold {MAX_NODES} nodes; this one holds more")

    # A bare string is a text node — the same shorthand renderNode accepts.
    if isinstance(node, (str, int, float, bool)):
        return _check_text(node, "text", _where)
    if not isinstance(node, dict):
        raise NodeValidationError(
            f"{_where}: a node must be an object or a string")

    unknown = sorted(set(node) - {"type", "props", "children"})
    if unknown:
        raise NodeValidationError(
            f"{_where}: unexpected key(s) {', '.join(unknown)} — a node is "
            f"type, props and children, and nothing else travels")

    node_type = node.get("type")
    if node_type not in ALLOWED:
        # Named rather than ignored: renderNode turns an unknown type into a
        # bare div, which renders SOMETHING and looks like it worked.
        raise NodeValidationError(
            f"{_where}: {node_type!r} is not a type this renders. "
            f"Allowed: {', '.join(sorted(ALLOWED))}.")

    children = node.get("children") or []
    if not isinstance(children, list):
        raise NodeValidationError(f"{_where}: children must be a list")

    return {
        "type": node_type,
        "props": _check_props(node_type, node.get("props"), _where),
        "children": [
            validate(child, _depth=_depth + 1, _counter=counter,
                     _where=f"{_where}.children[{index}]")
            for index, child in enumerate(children)
        ],
    }
